import ast,base64,hashlib,json,secrets,shlex,zlib
from pathlib import Path
HERE=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    check=json.loads((HERE/'LOCAL_VALIDATION.json').read_text());assert check['status']=='PASS' and check['repair_sha256']==sha(HERE/'repair.py')
    names=['repair.py','analysis_core.py','launch.py','client.py','receiver.py','INPUT_PINS.json','RECOVERY_PINS.json','LOCAL_VALIDATION.json','HISTORY_LINEAGE_COUNTS_CORRECTED.json','LINEAGE_METADATA_CORRECTION.json','EXECUTION_CARD.md']
    manifest=dict(files={n:sha(HERE/n) for n in names},new_forward=False,training=False,original_bitwise_gate_retained=True);(HERE/'PACKAGE_MANIFEST.json').write_text(json.dumps(manifest,indent=2)+'\n');names+=['PACKAGE_MANIFEST.json']
    cfg=dict(token=secrets.token_hex(32),pins={n:sha(HERE/n) for n in names});(HERE/'.private/connection.json').write_text(json.dumps(dict(token=cfg['token'],socks_port=53960,remote_port=18884)))
    project='/public/home/jiangxinwei.zr/work/paper04';remote=project+'/runs/'+HERE.name;py='/share/software/miniconda3.2025/envs/torch_demo_2025/bin/python'
    script='#!/bin/bash\n#SBATCH --partition=amd\n#SBATCH --ntasks=1\n#SBATCH --cpus-per-task=1\n#SBATCH --mem=12288M\n#SBATCH --time=01:00:00\n#SBATCH --no-requeue\n#SBATCH --job-name=tabm-eval-repair\n#SBATCH --output=slurm-%j.out\n#SBATCH --error=slurm-%j.err\nset -euo pipefail\numask 077\nsource '+project+'/frontend_compat_v1/environment.sh\nexport PYTHONPATH='+project+'/runs/dense_reference_batch_repair_v1_20261027_runtime/job_179602/science/runtime/numpy201:'+project+'/environment/vendor_py311_v1:${PYTHONPATH:-}\nexport OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 NUMEXPR_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1\nexec '+py+' -X utf8 -B '+remote+'/launch.py\n'
    payload={n:(HERE/n).read_bytes().decode('utf8') for n in names}
    code="import os,json,hashlib,subprocess,socket\nfrom pathlib import Path\nos.umask(0o077)\np=Path("+repr(remote)+")\nassert p.is_dir() and set(x.name for x in p.iterdir())=={'ARITHMETIC_DIAGNOSIS.json'},'DIAGNOSTIC_ONLY_REPAIR_DIRECTORY'\ns=socket.socket();s.bind(('127.0.0.1',18884));s.close()\nfiles="+repr(payload)+"\ncfg="+repr(cfg)+"\nfor n,v in files.items():\n b=v.encode('utf8');assert hashlib.sha256(b).hexdigest()==cfg['pins'][n];(p/n).write_bytes(b)\n(p/'.private.json').write_text(json.dumps(cfg))\nfor n,h in json.loads((p/'INPUT_PINS.json').read_text()).items():assert hashlib.sha256((p.parents[1]/n).read_bytes()).hexdigest()==h,'INPUT_SHA:'+n\n(p/'run.slurm').write_text("+repr(script)+")\nr=subprocess.run(['sacct','-j','183552','-n','-P','--format=JobID,State'],capture_output=True,text=True,timeout=20);assert '183552|PENDING' in r.stdout,'P4_DEPENDENCY_MUST_BE_UNSTARTED'\nr=subprocess.run(['sbatch','--parsable','run.slurm'],cwd=p,capture_output=True,text=True,timeout=30);assert r.returncode==0,r.stderr\njob=r.stdout.strip().split(';')[0];assert job.isdigit()\n(p/'JOB.json').write_text(json.dumps(dict(job_id=job,cpu=1,memory_gib=12,wall_seconds=3600,evaluation_only=True,new_forward=False,replaces_failed='183549',replaces_pending='183552')))\nr=subprocess.run(['scancel','183552'],capture_output=True,text=True,timeout=20)\n(p/'REPLACED_DEPENDENCY.json').write_text(json.dumps(dict(old_job='183552',new_job=job,cancel_returncode=r.returncode,cancel_stderr=r.stderr,old_job_was_pending=True)))\nwith (p/'receiver.log').open('ab') as f:proc=subprocess.Popen(["+repr(py)+",'-X','utf8','-B',str(p/'receiver.py')],stdin=subprocess.DEVNULL,stdout=f,stderr=f,start_new_session=True)\nprint('TABM_EVALUATION_REPAIR_SUBMITTED',job,'RECEIVER',proc.pid,'OLD_PENDING_CANCEL',r.returncode)\n"
    ast.parse(code);enc=base64.b64encode(zlib.compress(code.encode(),9)).decode();(HERE/'.private/RUN_IN_EXISTING_HPC.txt').write_text(py+' -c '+shlex.quote('import base64,zlib;exec(zlib.decompress(base64.b64decode('+repr(enc)+')))'))
    (HERE/'DELIVERY.json').write_text(json.dumps(dict(status='PREPARED_NOT_SUBMITTED',pins=cfg['pins'],new_forward=False,training=False),indent=2));print('EVALUATION_ONLY_REPAIR_PREPARED')
if __name__=='__main__':main()
